import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第71章 英语崩","description":"","frontmatter":{},"headers":[],"relativePath":"第71章_英语崩.md","filePath":"第71章_英语崩.md"}'),r={name:"第71章_英语崩.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第71章-英语崩" tabindex="-1">第71章 英语崩 <a class="header-anchor" href="#第71章-英语崩" aria-label="Permalink to &quot;第71章 英语崩&quot;">​</a></h1><p>我在窗边听见雨点敲在铁皮窗沿上，高二的夏天来得又湿又闷。</p><p>江苒坐在我前面，肩膀缩着，手里攥着听写本，指节发白。纸页被雨气浸得发软，上面一排排红圈，圈住她写错的字母。风从走廊灌进来，带着粉笔灰和潮水的味道。</p><p>她把本子扣过去，小声说，完了，我这次真的塌了。</p><p>我说没事，我帮你一起补。</p><p>陈默从后排探头，看一眼她的本子，咧嘴笑，说这单词认得你，你不认得它。顾远踢他凳子一下，让他闭嘴。林小满把自己的笔记推过来，上面贴满彩色小签。何晓凑过来，塞给江苒一块手帕，让她擦擦手心的汗。</p><p>叶老师抱着一摞本子走进来，目光在江苒脸上停了一秒，什么也没问。她把本子放下，粉笔在黑板上写了几个词，字迹圆润。她说，单词崩了很常见，崩了就一个一个捡回来。</p><p>下课后，叶老师把我们叫到办公室。办公室里有股旧纸和热茶的气息，窗台上摆着一盆绿萝，叶子上沾着水珠。她从抽屉里拿出一台小小的录音机，方方正正，按键已经磨得发亮。磁带转起来，有轻微的咔哒声。</p><p>她说，我教你们一个笨办法。单词要过三道水。眼睛看，嘴巴念，手写。每天早晚各走一遍，睡前再听一遍。耳朵记住了，手自然记得。</p><p>江苒点头，眼圈有点红。她说，叶老师，我背了就忘，早上背的，晚上就没了。</p><p>叶老师笑，说忘很正常。记住的东西，都是反复捞起来的。你试试把难词写在小纸条上，折成纸星星。背住一颗，就拆开一颗。拆开的星星攒着，攒满一罐，就奖励自己。</p><p>我立刻说，这个好，我陪你折。</p><p>叶老师又拿出两盒旧磁带，标签纸泛黄，上面是她手写的字母。她说，这是我以前录的，读音和例句都在里面。你们拿去听，跟着念，念出声来。声音从嘴里过一遍，比在心里转十遍管用。</p><p>江苒抱着磁带，像抱着救命的东西。她指尖碰到标签纸，轻轻摩挲，眼里有了点光。</p><p>晚上，雨还没停。宿舍走廊的灯暖黄，空气里有洗衣粉的香。江苒和我在自习角坐下，桌上摊着单词本，旁边放着一罐没折完的纸星星，还有那台录音机。</p><p>我按叶老师的方法，先带她读。读出声来，声音在空荡的走廊里回响，有点不好意思，但读了几遍就顺了。秦浩从水房回来，提着暖壶，笑着说，你们这是在开英文晚会吗。赵晴跟在他后面，递给江苒一杯热水，说慢慢来，我上学期也这样。</p><p>江苒喝了口热水，热气扑在脸上，睫毛上沾了细小的水雾。她拿起笔，把最难的几个词抄在小纸条上，折成小小的星星。她的手指很巧，纸条在她手里翻几下，就鼓成一颗。她折好一颗，放在我手心，说，你帮我收着。</p><p>我说好，你背住一颗，我就还你一颗。</p><p>她先背第一颗。嘴唇轻轻动，声音小小的。我听见她的发音，有点抖，但每个音都咬得很认真。窗外雨声细密，落在雨棚上，像有人在轻轻鼓掌。</p><p>背到第五颗，她卡住了。那个词很长，字母绕来绕去。她皱眉，额头抵着桌子，头发散下来，遮住耳朵。我把录音机按开，叶老师的声音流出来，温和清晰，带着磁带的沙沙声。例句念了两遍，江苒跟着念，舌尖顶着牙齿，气息从唇间出来。</p><p>她又试了一次，还是错了一个字母。她把笔一放，说我好笨。</p><p>我从口袋里摸出一颗海盐糖。这是宋阿婆上次赶集带来的，用黄纸包着，咸里带甜。阿婆说，读书累了，就含一颗，提神。她说话时脸上的皱纹笑成一朵花，身上有阳光晒过被子的味道。</p><p>我剥开糖纸，把糖放在她手心。我说，先吃颗糖，咸甜味在嘴里化开了，脑子就松了。</p><p>她把糖含进嘴里，腮帮子鼓起一点。她说，好咸，又好甜。</p><p>我说，对，咸了，记忆就结晶了。</p><p>她被逗笑，眼睛弯起来。她重新拿起那个词，又写了三遍。这次对了。她开心地拆开一颗纸星星，纸展开，露出里面的词。她把纸贴在脸颊上，凉凉的，很舒服。</p><p>林小满晚自习后过来找我们，怀里抱着一叠卡片。她说，我帮你们做了遮挡卡，盖住中文，想英文，盖住英文，想中文。她演示了一遍，动作很快。何晓也来了，带来一小包话梅，说背累了就吃一颗，酸味能让人清醒。</p><p>陈默和顾远也挤过来。陈默说，我贡献一个办法。我背单词就边走边背，走三步念一个。顾远说，我的办法是睡前在脑子里放电影，把单词串成故事。大家七嘴八舌，笑声把雨声都盖住了。</p><p>江苒的眼睛亮起来。她说，那我也编个故事，把今天错的词都放进去。</p><p>她编的故事里，有雾，有海，有南雾县老街的灯。她把单词藏在故事里，一个一个用掉。我帮她记着，错了就提醒。她讲完，脸有点红，说故事好土。</p><p>我说不土，很好记。土的办法，才长久。</p><p>她低头继续折星星，纸角在她指尖翻飞，发出细细的脆响。录音机里的声音停了一会儿，只剩磁带空转的沙沙声，像雨落在远处海面上。她忽然停下笔，抬头看我，眼里映着灯光。她说，沈聿，你说我能行吗。我把手里的星星放在她桌上，排成一排，说你看，这些都是你刚才捡回来的。她数着星星，唇角慢慢松开。走廊尽头有人轻轻哼歌，混着暖壶的热气，夜显得很软。她又含了一颗海盐糖，咸甜在她舌尖化开，她皱起的眉也化开了。她说，明天我想再早点来，把剩下的也拆完。</p><p>夜深了，走廊安静下来，只剩雨声和磁带转动的轻响。叶老师查寝经过，看见我们桌上的星星罐，停下脚步。她拿起一颗，放在灯下看，说折得真好。</p><p>她坐下来，轻声问江苒，今天记住多少。</p><p>江苒数了数拆开的纸，说有大半罐了。</p><p>叶老师点头，说很好。记住，别在心里骂自己。脑子怕紧张，越骂越紧。你把它当朋友，多见几面，就熟了。</p><p>江苒点头，把剩下的海盐糖分给叶老师一颗。叶老师含着糖，笑起来，眼角有细纹。她说，宋阿婆的糖，还是这个味道。</p><p>我送叶老师出门，她忽然回头，把一盒没拆封的旧磁带放在我手里。磁带外壳有点裂，标签上空着，没写字。她压低声音，说这盒别急着听。</p><p>我愣住，问里面是什么。</p><p>她看看走廊那头的江苒，灯光落在江苒发顶，柔软安静。叶老师说，里面是她以前的声音。她自己录的，录完就哭了，一直不敢听。等她这次站起来，你们再一起听。</p><p>我握紧那盒磁带，塑料壳冰凉，里面似乎还藏着一段没说完的话。雨声里，我听见江苒在叫我，声音轻轻的，问我明天能不能早点来，再陪她过一遍三道水。</p><p>我把磁带藏进口袋，回头应她，好。转身时，我在想，那卷没写名字的磁带里，到底录了什么，让叶老师也放得这样轻。</p>',42)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
